package com.una.embyhub.mapper;

import com.baomidou.mybatisplus.core.mapper.BaseMapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.una.embyhub.model.dto.request.playrecords.UserPlayStats;
import com.una.embyhub.model.dto.response.playrecords.PlayCountSummary;
import com.una.embyhub.model.dto.response.playrecords.PlayRecordsResponse;
import com.una.embyhub.model.entity.PlayRecords;
import java.util.Date;
import java.util.List;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

public interface PlayRecordsMapper extends BaseMapper<PlayRecords> {
   @Select({"<script>", "WITH PlaySessions AS (", "    SELECT ", "        s.emby_user_id,", "        s.emby_user_name,", "        s.content,", "        s.device,", "        s.emby_info_id,", "        s.play_date AS start_time,", "        MIN(e.play_date) AS end_time,", "        TIMESTAMPDIFF(SECOND, s.play_date, MIN(e.play_date)) AS duration_seconds", "    FROM play_records s", "    JOIN play_records e ", "        ON s.emby_user_id = e.emby_user_id", "        AND s.content = e.content", "        AND s.device = e.device", "        AND s.emby_info_id = e.emby_info_id", "        AND (e.record_type = 'VideoPlaybackStopped' or e.record_type = 'playback.stop')", "        AND e.play_date &gt; s.play_date", "        <if test=\"embyInfoId != null\">", "            AND e.emby_info_id = #{embyInfoId}", "        </if>", "    WHERE 1 = 1", "        AND (s.record_type = 'VideoPlayback' or s.record_type = 'playback.start')", "        <if test=\"embyInfoId != null\">", "            AND s.emby_info_id = #{embyInfoId}", "        </if>", "        <if test=\"userName != null and userName != ''\">", "            AND s.emby_user_name LIKE CONCAT('%', #{userName}, '%')", "        </if>", "        <if test=\"startDate != null\">", "            AND DATE(s.play_date) &gt;= #{startDate}", "        </if>", "        <if test=\"endDate != null\">", "            AND DATE(s.play_date) &lt;= #{endDate}", "        </if>", "    GROUP BY ", "        s.emby_user_id, ", "        s.emby_user_name, ", "        s.content, ", "        s.device, ", "        s.emby_info_id, ", "        s.play_date", "),", "DailyContentTotals AS (", "    SELECT", "        emby_user_id,", "        emby_user_name,", "        content,", "        device,", "        emby_info_id,", "        DATE(start_time) AS play_day,", "        SUM(duration_seconds) AS total_seconds,", "        COUNT(*) AS play_times", "    FROM PlaySessions", "    GROUP BY ", "        emby_user_id, ", "        emby_user_name, ", "        content, ", "        device, ", "        emby_info_id, ", "        DATE(start_time)", "),", "UserDailyTotals AS (", "    SELECT", "        emby_user_id,", "        emby_user_name,", "        emby_info_id,", "        play_day,", "        SUM(total_seconds) AS total_seconds,", "        SUM(play_times) AS total_play_times", "    FROM DailyContentTotals", "    GROUP BY ", "        emby_user_id, ", "        emby_user_name, ", "        emby_info_id, ", "        play_day", ")", "SELECT", "    emby_user_id,", "    emby_user_name,", "    emby_info_id AS embyInfoId,", "    ei.server_name AS serverName,", "    play_day,", "    total_play_times AS play_times,", "    CONCAT(", "        IF(total_seconds &gt;= 3600, CONCAT(FLOOR(total_seconds / 3600), '小时'), ''),", "        IF(total_seconds &gt;= 60, CONCAT(FLOOR((total_seconds % 3600) / 60), '分钟'), ''),", "        MOD(total_seconds, 60),", "        '秒'", "    ) AS total_play_time", "FROM UserDailyTotals", "LEFT JOIN emby_info ei ON UserDailyTotals.emby_info_id = ei.id", "ORDER BY ", "    play_day DESC, ", "    total_play_times DESC,", "    total_seconds DESC", "</script>"})
   List<UserPlayStats> getUserPlayStats(
      @Param("userName") String userName, @Param("startDate") Date startDate, @Param("endDate") Date endDate, @Param("embyInfoId") Long embyInfoId
   );

   @Select({"<script>WITH PlaySessions AS (    SELECT         s.emby_user_id,         s.emby_user_name,         s.content,         s.device,         s.emby_info_id,         s.play_date AS start_time,         MIN(e.play_date) AS end_time,         TIMESTAMPDIFF(SECOND, s.play_date, MIN(e.play_date)) AS duration_seconds     FROM play_records s     JOIN play_records e         ON s.emby_user_id = e.emby_user_id         AND s.content = e.content         AND s.device = e.device         AND s.emby_info_id = e.emby_info_id         AND (e.record_type = 'VideoPlaybackStopped' or e.record_type = 'playback.stop')         AND e.play_date &gt; s.play_date         <if test=\"embyInfoId != null\">            AND e.emby_info_id = #{embyInfoId}         </if>     WHERE         (s.record_type = 'VideoPlayback' or s.record_type = 'playback.start')         <if test=\"embyInfoId != null\">            AND s.emby_info_id = #{embyInfoId}         </if>     GROUP BY         s.emby_user_id,         s.emby_user_name,         s.content,         s.device,         s.emby_info_id,         s.play_date ), DailyContentTotals AS (    SELECT         emby_user_id,         emby_user_name,         content,         device,         emby_info_id,         DATE(start_time) AS play_date,         MIN(start_time) AS first_play_start_time,         MAX(end_time) AS last_play_end_time,         SUM(duration_seconds) AS total_seconds     FROM PlaySessions     WHERE 1 = 1         <if test=\"userName != null and userName != ''\">            AND emby_user_name LIKE CONCAT('%', #{userName}, '%')         </if>        <if test=\"startTime != null\">            AND start_time &gt;= #{startTime}         </if>        <if test=\"endTime != null\">            AND start_time &lt; DATE_ADD(#{endTime}, INTERVAL 1 DAY)         </if>    GROUP BY         emby_user_id,         emby_user_name,         content,         device,         emby_info_id,         DATE(start_time) ) SELECT     emby_user_id,     emby_user_name,     emby_info_id AS embyInfoId,     ei.server_name AS serverName,     play_date,     content,     device,     first_play_start_time,     last_play_end_time,     CONCAT(         IF(total_seconds &gt;= 3600, CONCAT(FLOOR(total_seconds / 3600), '小时'), ''),         IF(total_seconds &gt;= 60, CONCAT(FLOOR((total_seconds % 3600) / 60), '分钟'), ''),         MOD(total_seconds, 60),         '秒'     ) AS total_play_time FROM DailyContentTotals LEFT JOIN emby_info ei ON DailyContentTotals.emby_info_id = ei.id WHERE 1 = 1     <if test=\"startTime != null\">        AND last_play_end_time &gt;= #{startTime}     </if>    <if test=\"endTime != null\">        AND last_play_end_time &lt; DATE_ADD(#{endTime}, INTERVAL 1 DAY)     </if>ORDER BY     first_play_start_time DESC,     emby_user_id,     total_seconds DESC </script>"})
   Page<PlayRecordsResponse> selectDailyStats(
      Page<PlayRecords> page,
      @Param("userName") String userName,
      @Param("startTime") Date startTime,
      @Param("endTime") Date endTime,
      @Param("embyInfoId") Long embyInfoId
   );

   @Select({"<script>", "SELECT", "    id,", "    emby_user_id,", "    play_date,", "    record_type,", "    device,", "    content,", "    emby_user_name,", "    emby_info_id", "FROM play_records", "WHERE (record_type = 'VideoPlayback' OR record_type = 'playback.start')", "<if test=\"userName != null and userName != ''\">", "    AND emby_user_name = #{userName}", "</if>", "ORDER BY play_date DESC", "LIMIT #{limit}", "</script>"})
   List<PlayRecords> findRecentPlays(@Param("userName") String userName, @Param("limit") Integer limit);

   @Select({"<script>", "SELECT", "    content,", "    COUNT(*) AS playCount", "FROM play_records", "WHERE (record_type = 'VideoPlayback' OR record_type = 'playback.start')", "<if test=\"startTime != null\">", "    AND play_date &gt;= #{startTime}", "</if>", "<if test=\"endTime != null\">", "    AND play_date &lt; #{endTime}", "</if>", "<if test=\"embyInfoId != null\">", "    AND emby_info_id = #{embyInfoId}", "</if>", "GROUP BY content", "HAVING content IS NOT NULL", "ORDER BY playCount DESC", "</script>"})
   List<PlayCountSummary> summaryByRange(@Param("startTime") Date startTime, @Param("endTime") Date endTime, @Param("embyInfoId") Long embyInfoId);
}
